function bumpSkillVersion(id) {
  var s = skillById(id);
  if (!s) return null;
  var ver = (s.version || 'v0.1.0').replace(/^v/, '').split('.').map(function (x) { return parseInt(x, 10) || 0; });
  while (ver.length < 3) ver.push(0);
  ver[1] += 1;
  ver[2] = 0;
  var newVersion = 'v' + ver.join('.');
  var list = getCustomSkills();
  var customHit = list.find(function (x) { return x.id === id; });
  if (customHit) {
    list = list.map(function (x) {
      if (x.id !== id) return x;
      return Object.assign({}, x, { version: newVersion, status: 'draft', updatedAt: new Date().toISOString().slice(0, 10) });
    });
    setCustomSkills(list);
  } else {
    SKILL_CATALOG.forEach(function (x) {
      if (x.id === id) {
        x.version = newVersion;
        x.status = 'draft';
        x.updatedAt = new Date().toISOString().slice(0, 10);
      }
    });
  }
  return skillById(id);
}

