function mkText(str, size, weight, color) {
  const t = figma.createText();
  t.fontName = { family: 'Inter', style: weight };
  t.characters = str;
  t.fontSize = size;
  t.fills = [{ type: 'SOLID', color }];
  return t;
}

async function loadFonts() {
  await figma.loadFontAsync({ family: 'Inter', style: 'Regular' });
  await figma.loadFontAsync({ family: 'Inter', style: 'Medium' });
  await figma.loadFontAsync({ family: 'Inter', style: 'Semi Bold' });
}
await loadFonts();

const screens = [
  { name: '01 · Skills 管理', sub: '10-skills-management.html · 新增', x: 0, w: 1440, h: 900, accent: { r: 0.03, g: 0.5, b: 0.36 } },
  { name: '02 · 智能体配置', sub: '05-agent-detail.html · Skills 绑定/预览', x: 1520, w: 1440, h: 900, accent: { r: 0.23, g: 0.51, b: 0.96 } },
  { name: '03 · 用户对话', sub: '09-user-chat.html · 临时 Skills +', x: 3040, w: 1280, h: 820, accent: { r: 0.55, g: 0.36, b: 0.96 } },
