];

const created = [];
for (const s of screens) {
  let frame = page.children.find(n => n.type === 'FRAME' && n.name === s.name);
  if (!frame) {
    frame = figma.createFrame();
    frame.name = s.name;
    page.appendChild(frame);
  }
  frame.resize(s.w, s.h);
  frame.x = s.x;
  frame.y = 120;
  frame.fills = [{ type: 'SOLID', color: { r: 0.97, g: 0.98, b: 0.99 } }];
  frame.strokes = [{ type: 'SOLID', color: { r: 0.88, g: 0.9, b: 0.93 } }];
  frame.strokeWeight = 1;
  frame.cornerRadius = 12;
