  // header bar
  let header = frame.children.find(n => n.name === 'Header');
  if (!header) {
    header = figma.createFrame();
    header.name = 'Header';
    frame.appendChild(header);
  }
  header.resize(s.w, 56);
  header.x = 0; header.y = 0;
  header.fills = [{ type: 'SOLID', color: s.accent }];
  header.layoutMode = 'HORIZONTAL';
  header.primaryAxisAlignItems = 'SPACE_BETWEEN';
  header.counterAxisAlignItems = 'CENTER';
  header.paddingLeft = 24; header.paddingRight = 24;
  while (header.children.length) header.children[0].remove();
  const ht = mkText(s.name.replace(/^\d+ · /, ''), 16, 'Semi Bold', { r: 1, g: 1, b: 1 });
  header.appendChild(ht);
  const hs = mkText(s.sub, 12, 'Regular', { r: 1, g: 1, b: 1 });
  header.appendChild(hs);

  // placeholder body note
  let body = frame.children.find(n => n.name === 'BodyPlaceholder');
  if (!body) {
    body = figma.createFrame();
    body.name = 'BodyPlaceholder';
    frame.appendChild(body);
  }
  body.resize(s.w - 48, s.h - 120);
  body.x = 24; body.y = 80;
