function placeCapture(captureId, targetFrameId, placeholderId) {
  const capture = figma.getNodeById(captureId);
  const target = figma.getNodeById(targetFrameId);
  const placeholder = figma.getNodeById(placeholderId);
  if (!capture || !target || !placeholder) return { captureId, ok: false, reason: 'missing node' };

