  capture.x = 0;
  capture.y = 56; // below header bar

  // Scale down if too large
  const maxW = target.width;
  const maxH = target.height - 56;
  if (capture.width > maxW || capture.height > maxH) {
    const scale = Math.min(maxW / capture.width, maxH / capture.height, 1);
    capture.resize(capture.width * scale, capture.height * scale);
  }

  target.clipsContent = true;
  return { captureId, ok: true, w: capture.width, h: capture.height };
}

