 * Cleans Skills 配置 page and places captures 1:1 inside labeled frames (no scale/clip).
 */
(async () => {
  const PAGE_ID = '46:312';
  const FRAMES = [
    { frameId: '62:312', label: '01 · Skills 管理' },
    { frameId: '62:318', label: '02 · 智能体配置' },
