    return;
  }
  await figma.setCurrentPageAsync(page);

  const deleted = [];
  for (const child of [...page.children]) {
    const inFrame = FRAMES.some((f) => f.frameId === child.id);
    if (!inFrame && child.type === 'FRAME') {
      deleted.push(child.id);
      child.remove();
    }
  }

  for (const { frameId } of FRAMES) {
