/**
 * Run in Figma: Plugins > Development > Import plugin from manifest
 * Point to design/figma-plugin/manifest.json
 *
 * Places latest HTML captures into labeled frames on Skills 配置 page.
 */
(async () => {
  const PAGE_ID = '46:312';
  const PAIRS = [
    ['70:2', '62:312'],
    ['71:2', '62:318'],
    ['72:2', '62:324'],
    ['73:2', '62:330'],
    ['74:2', '62:336'],
  ];

  const page = await figma.getNodeByIdAsync(PAGE_ID);
  if (!page || page.type !== 'PAGE') {
    figma.closePlugin('Page Skills 配置 not found');
    return;
  }
  await figma.setCurrentPageAsync(page);

  const deleted = [];
  const placed = [];

  for (const [capId, frameId] of PAIRS) {
    const cap = figma.getNodeById(capId);
    const frame = figma.getNodeById(frameId);
    if (!cap || !frame || frame.type !== 'FRAME') {
      placed.push({ capId, frameId, ok: false });
      continue;
    }
    for (const child of [...frame.children]) {
      if (child.name !== 'Header') {
        deleted.push(child.id);
        child.remove();
      }
    }
    frame.appendChild(cap);
    cap.x = 0;
    cap.y = 56;
    frame.clipsContent = false;
    if (cap.width > frame.width) {
      const scale = frame.width / cap.width;
      cap.resize(frame.width, cap.height * scale);
    }
    frame.resize(frame.width, Math.max(frame.height, cap.y + cap.height + 24));
    placed.push({ capId, frameId, ok: true, frameHeight: frame.height });
  }

  for (const child of [...page.children]) {
    if (child.type !== 'FRAME') continue;
    const keep = PAIRS.some((p) => p[1] === child.id || p[0] === child.id);
    if (!keep && /Skills|客服|对话|运行|选择|管理|Placeholder|capture/i.test(child.name)) {
      deleted.push(child.id);
      child.remove();
    }
  }

  figma.notify('Placed ' + placed.filter((p) => p.ok).length + ' screens');
  figma.closePlugin(JSON.stringify({ placed, deletedCount: deleted.length }, null, 2));
})();

