 * Figma: Plugins > Development > Import plugin from manifest
 */
(async () => {
  const PAGE_ID = '46:312';
  const FRAME_LABELS = [
    { frameId: '62:312', match: /Skills 管理|10-skills/i },
    { frameId: '62:318', match: /客服助手|智能体配置|agent-detail/i },
    { frameId: '62:324', match: /用户对话|user-chat|对话 ·/i },
