  if (!page || page.type !== 'PAGE') {
    figma.closePlugin('Page Skills 配置 not found');
    return;
  }
  await figma.setCurrentPageAsync(page);

  const deleted = [];
  const placed = [];

  function removeNode(n) {
    if (n) { deleted.push(n.id); n.remove(); }
  }

  // Remove placeholder text / BodyPlaceholder
  page.findAll(function (n) {
    if (n.type === 'TEXT' && /待 HTML|BodyPlaceholder|渲染补充|捕获填充/i.test(n.characters || '')) {
      return true;
    }
    if (n.name === 'BodyPlaceholder') return true;
    return false;
  }).forEach(removeNode);

  const keepFrameIds = FRAME_LABELS.map(function (f) { return f.frameId; });
  const orphans = page.children.filter(function (c) {
    if (c.type !== 'FRAME') return false;
    if (keepFrameIds.indexOf(c.id) >= 0) return false;
    if (/Skills 配置|原型页面集|board/i.test(c.name)) return false;
    return /Skills|客服|对话|运行|选择|管理|配置 ·|资源 ·|capture/i.test(c.name);
  });

  // Match orphans to frames
  const used = new Set();
  for (const label of FRAME_LABELS) {
    const frame = figma.getNodeById(label.frameId);
    if (!frame || frame.type !== 'FRAME') continue;

    for (const child of [...frame.children]) {
      if (child.name !== 'Header') removeNode(child);
    }

    let cap = orphans.find(function (o) {
      return !used.has(o.id) && label.match.test(o.name);
    });
    if (!cap) {
      cap = orphans.find(function (o) { return !used.has(o.id); });
    }
    if (!cap) {
      placed.push({ frameId: label.frameId, ok: false, reason: 'no capture found' });
