(async () => {
  const PAGE_ID = '46:312';
  const BOARD_NAMES = [/Skills 配置 · 原型页面集/, /figma-skills-board/i];
  const BOARD_MIN_WIDTH = 6000;

  const page = await figma.getNodeByIdAsync(PAGE_ID);
  if (!page || page.type !== 'PAGE') {
    figma.closePlugin('Page not found');
    return;
  }
  await figma.setCurrentPageAsync(page);

  const deleted = [];

  page.findAll(function (n) {
    if (n.type === 'TEXT' && /待 HTML|BodyPlaceholder|渲染补充|捕获填充/i.test(n.characters || '')) return true;
    if (n.name === 'BodyPlaceholder') return true;
    return false;
  }).forEach(function (n) { deleted.push(n.id); n.remove(); });

  var board = page.children.find(function (c) {
    return c.type === 'FRAME' && (c.width >= BOARD_MIN_WIDTH || BOARD_NAMES.some(function (re) { return re.test(c.name); }));
  });

  var removeIds = ['62:312','62:318','62:324','62:330','62:336','59:2','63:2','65:2','66:2','68:2','70:2','71:2','72:2','73:2','74:2','76:2','77:2'];
  for (var i = 0; i < removeIds.length; i++) {
    var n = figma.getNodeById(removeIds[i]);
    if (n && (!board || n.id !== board.id)) {
      deleted.push(n.id);
      n.remove();
    }
  }

  for (var j = 0; j < page.children.length; j++) {
    var child = page.children[j];
    if (board && child.id === board.id) continue;
    if (child.type !== 'FRAME') continue;
    if (/01 ·|02 ·|03 ·|04 ·|05 ·|Skills 管理|智能体配置|用户对话|运行监控|选择 Skill/i.test(child.name)) {
      deleted.push(child.id);
      child.remove();
    } else if (child.width < 6500 && /Skills|客服|对话|运行|选择|管理|配置 ·|资源 ·/i.test(child.name)) {
      deleted.push(child.id);
      child.remove();
    }
  }

  if (board) {
    board.x = 0;
    board.y = 0;
    board.name = 'Skills 配置 · 原型页面集';
  }

  figma.notify('Cleaned ' + deleted.length + ' nodes. Board: ' + (board ? board.id : 'missing — re-run capture'));
  figma.closePlugin(JSON.stringify({ boardId: board ? board.id : null, deleted: deleted }, null, 2));
})();

